def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive_opponents = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        return max(0.0, min(budget, 20.0))

    prev_bids = []
    active_threats = 0
    max_prev_bid = 0.0
    min_opp_req = WATER_REQ
    for opp in alive_opponents:
        req = opp.get('water_requirement', WATER_REQ)
        if req < min_opp_req:
            min_opp_req = req
        prev = opp.get('previous_trace', {})
        bid = None
        if prev:
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(bid)
            if bid > max_prev_bid:
                max_prev_bid = bid
            if bid >= 80:
                active_threats += 1

    total_demand_units = WATER_REQ
    for opp in alive_opponents:
        total_demand_units += opp.get('water_requirement', WATER_REQ)

    tight_supply = supply <= total_demand_units * 0.55
    medium_tight = supply <= total_demand_units * 0.7

    emergency = hp <= 3 or no_water >= 1
    severe_emergency = hp <= 2 or no_water >= 2

    if severe_emergency:
        target = max(100.0, max_prev_bid + 2.0)
        if supply <= WATER_REQ:
            target = max(target, 112.0)
        return max(0.0, min(budget, target))

    if emergency:
        target = 92.0
        if max_prev_bid >= 98:
            target = max(target, max_prev_bid + 1.0)
        if tight_supply:
            target += 8.0
        return max(0.0, min(budget, target))

    if tight_supply:
        if active_threats >= 2:
            target = 99.5
        elif max_prev_bid > 0:
            target = max(72.0, max_prev_bid + 1.0)
        else:
            target = 75.0
        if budget < 250:
            target -= 10.0
        return max(0.0, min(budget, target))

    if medium_tight:
        target = 61.0
        if max_prev_bid >= 98:
            target = 68.0
        if day >= 8 and hp >= 5:
            target -= 6.0
        return max(0.0, min(budget, target))

    target = 34.0
    if max_prev_bid < 50 and max_prev_bid > 0:
        target = max(34.0, max_prev_bid + 1.0)
    if day >= 8:
        target = 28.0
    return max(0.0, min(budget, target))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    alive_opps = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    # Base safety: if very low HP, buy maximum feasible water.
    if my_status['hp'] is not None and my_status['hp'] <= 2:
        return float(min(my_status['budget'], DAILY_SALARY * 0.95))

    # Read yesterday bids from immediate previous_trace only.
    yesterday_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    # If others heavily bid yesterday, slightly undercut to still secure allocation.
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        # Estimate typical aggressive anchor around ~DAILY_SALARY.
        aggressive_anchor = DAILY_SALARY * 1.08  # ~97.2

        # Determine target bid: undercut highest but stay near anchor.
        # Also adjust by current supply: higher supply allows lower bid.
        supply_factor = 1.0
        if supply >= (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
            supply_factor = 0.92
        else:
            supply_factor = 1.00

        # If they bid near anchor, bid just below highest.
        if highest_prev_bid >= aggressive_anchor * 0.95:
            target = min(highest_prev_bid - 1.0, aggressive_anchor) * supply_factor
        else:
            # Otherwise, bid around max(highest, half salary) with mild undercut.
            target = max(highest_prev_bid, DAILY_SALARY * 0.55) * supply_factor

        # Keep within budget and avoid overspending early.
        # Ensure we can sustain multiple days: leave some budget buffer.
        budget_cap = my_status['budget'] * 0.35 if day <= 3 else my_status['budget'] * 0.45
        bid = min(float(target), float(budget_cap), float(my_status['budget']))

        # If bid becomes too small relative to need, bump.
        if bid < DAILY_SALARY * 0.45 and my_status['hp'] is not None and my_status['hp'] <= 5:
            bid = min(float(my_status['budget']), DAILY_SALARY * 0.65)

        return float(max(0.0, bid))

    # No trace bids available: conservative mid bid.
    # If supply is low, bid higher to avoid no-water days.
    if supply < (MIN_SUPPLY + MAX_SUPPLY) / 2.0:
        return float(min(my_status['budget'], DAILY_SALARY * 0.65))
    return float(min(my_status['budget'], DAILY_SALARY * 0.55))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    yesterday_bids = []
    for opp_id, opp in opponents_status.items():
        if opp['alive']:
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                yesterday_bids.append(prev['bid'])

    highest_prev_bid = 0
    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    aggressive_threshold = DAILY_SALARY * 0.6

    if highest_prev_bid >= aggressive_threshold:
        bid = max(DAILY_SALARY * 0.65, highest_prev_bid + 5)
    else:
        bid = DAILY_SALARY * 0.7

    return min(my_status['budget'], bid)
